# table: [(망 주소, 프리픽스 길이, 다음 홉)]
def longest_prefix_match(table, dst):
    best, best_len = None, -1
    for net, plen, next_hop in table:
        mask = (0xFFFFFFFF << (32 - plen)) & 0xFFFFFFFF
        if (dst & mask) == net and plen > best_len:
            best, best_len = next_hop, plen  # 더 긴 일치
    return best

