circuit-breaker.pseudocode:
class CircuitBreaker:
    def __init__(self, threshold, timeout):
        self.state = 'CLOSED'
        self.failures = 0
        self.threshold = threshold
        self.timeout = timeout
        self.opened_at = 0

    def call(self, func, fallback):
        if self.state == 'OPEN':
            if now() - self.opened_at < self.timeout:
                return fallback()  # 빠른 실패
            self.state = 'HALF_OPEN'  # 시험 호출 허용
        try:
            result = func()
        except Exception:
            self.failures += 1
            if (self.state == 'HALF_OPEN'
                    or self.failures >= self.threshold):
                self.state = 'OPEN'  # 차단 시작
                self.opened_at = now()
            return fallback()
        self.state = 'CLOSED'  # 성공 시 정상 복귀
        self.failures = 0
        return result

circular-dependency.pseudocode:
def find_cycle(graph):  # graph: 모듈 -> 의존 모듈 목록
    WHITE, GRAY, BLACK = 0, 1, 2
    color = {v: WHITE for v in graph}

    def dfs(u, path):
        color[u] = GRAY  # 탐색 중
        path.append(u)
        for v in graph[u]:
            if color[v] == GRAY:  # 역방향 간선 = 순환
                return path[path.index(v):] + [v]
            if color[v] == WHITE:
                cyc = dfs(v, path)
                if cyc:
                    return cyc
        color[u] = BLACK  # 탐색 완료
        path.pop()
        return None

    for v in graph:
        if color[v] == WHITE:
            cyc = dfs(v, [])
            if cyc:
                return cyc  # 예: ['A', 'B', 'A']
    return None  # 순환 없음

circular-queue.pseudocode:
class CircularQueue:
    def __init__(self, n):
        self.q = [None] * n
        self.n = n
        self.front = self.rear = 0  # 한 칸 비우기 방식

    def is_empty(self):
        return self.front == self.rear

    def is_full(self):
        return (self.rear + 1) % self.n == self.front

    def enqueue(self, x):
        if self.is_full():
            raise OverflowError('queue full')
        self.rear = (self.rear + 1) % self.n
        self.q[self.rear] = x

    def dequeue(self):
        if self.is_empty():
            raise IndexError('queue empty')
        self.front = (self.front + 1) % self.n
        return self.q[self.front]
